import{_ as t,o as c,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"03 — Quản trị Công ty, Không gian làm việc & Chế độ Cá nhân (Agency, Workspace & Personal Studio)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/03-agency-workspace-management.md","filePath":"ba/03-agency-workspace-management.md"}'),d={name:"ba/03-agency-workspace-management.md"};function a(r,e,l,g,i,h){return c(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_03-—-quan-tri-cong-ty-khong-gian-lam-viec-che-đo-ca-nhan-agency-workspace-personal-studio" tabindex="-1">03 — Quản trị Công ty, Không gian làm việc &amp; Chế độ Cá nhân (Agency, Workspace &amp; Personal Studio) <a class="header-anchor" href="#_03-—-quan-tri-cong-ty-khong-gian-lam-viec-che-đo-ca-nhan-agency-workspace-personal-studio" aria-label="Permalink to &quot;03 — Quản trị Công ty, Không gian làm việc &amp; Chế độ Cá nhân (Agency, Workspace &amp; Personal Studio)&quot;">​</a></h1><p>&gt; [&lt;&lt; 02 - Authentication &amp; Profile](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/02-authentication-profile.md) | [Overview](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/00-overview.md) | [Tiếp: 04 - Media Package &amp; Campaign &gt;&gt;](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/04-media-package-campaign.md) &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.4 Agency &amp; Workspace</code> — 26 FR (<code>3.4.1</code> – <code>3.4.26</code>)</strong> | <code>UC-014</code> – <code>UC-039</code>. &gt; Kết hợp kiến trúc <strong>Hybrid Personal Studio + Solo Workspace Mode (<code>workspaceMode = &quot;PERSONAL&quot; | &quot;AGENCY&quot;</code>)</strong> theo <code>docs/feature/personal-workspace-mode/spec.md</code>.</p><hr><h2 id="_1-bang-tong-hop-26-yeu-cau-chuc-nang-chuan-3-4-1-–-3-4-26" tabindex="-1">1. Bảng Tổng hợp 26 Yêu cầu Chức năng Chuẩn (<code>3.4.1</code> – <code>3.4.26</code>) <a class="header-anchor" href="#_1-bang-tong-hop-26-yeu-cau-chuc-nang-chuan-3-4-1-–-3-4-26" aria-label="Permalink to &quot;1. Bảng Tổng hợp 26 Yêu cầu Chức năng Chuẩn (`3.4.1` – `3.4.26`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (Atomic CRUD FR)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.4.1</code></strong></td><td style="text-align:center;"><code>UC-014</code></td><td style="text-align:left;"><strong>Create Agency</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Tạo mới một Công ty truyền thông (<code>Agency</code>) hoặc tự động khởi tạo <code>Personal Hub</code> (<code>isPersonalHub</code>) khi dùng chế độ cá nhân; người tạo trở thành <code>Owner</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.2</code></strong></td><td style="text-align:center;"><code>UC-015</code></td><td style="text-align:left;"><strong>View Agency List</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xem danh sách các <code>Agency</code> mà người dùng sở hữu hoặc đang là thành viên chính thức.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.3</code></strong></td><td style="text-align:center;"><code>UC-016</code></td><td style="text-align:left;"><strong>View Agency Detail</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xem thông tin tổng quan, hồ sơ thương hiệu công ty, số liệu thống kê và gói cước của <code>Agency</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.4</code></strong></td><td style="text-align:center;"><code>UC-017</code></td><td style="text-align:left;"><strong>Update Agency Profile</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Cập nhật thông tin hồ sơ công ty (Tên, Logo, Tagline, Quy mô, Lĩnh vực, Mã số thuế, Địa chỉ, Website, Thông tin liên hệ).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.5</code></strong></td><td style="text-align:center;"><code>UC-018</code></td><td style="text-align:left;"><strong>Delete Agency</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Xóa mềm (<code>soft-delete</code>) một <code>Agency</code> khi không còn chiến dịch/hóa đơn treo.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.6</code></strong></td><td style="text-align:center;"><code>UC-019</code></td><td style="text-align:left;"><strong>View Agency Members</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xem danh sách thành viên thuộc <code>Agency</code> và danh sách các lời mời đang chờ phản hồi (<code>PENDING</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.7</code></strong></td><td style="text-align:center;"><code>UC-020</code></td><td style="text-align:left;"><strong>View Agency Organization Chart</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xem sơ đồ tổ chức trực quan (cây phân cấp <code>Owner → Workspaces → Manager &amp; Creators</code>) của toàn bộ <code>Agency</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.8</code></strong></td><td style="text-align:center;"><code>UC-021</code></td><td style="text-align:left;"><strong>Invite Agency Member</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Gửi lời mời tham gia <code>Agency</code> qua email (hỗ trợ chọn ngôn ngữ email <code>vi</code>/<code>en</code>, mẫu email, lời nhắn cá nhân, xem trước trực tiếp bản mẫu email mời và tùy chọn gán thẳng vào <code>Workspace</code> + <code>WorkspaceRole</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.9</code></strong></td><td style="text-align:center;"><code>UC-022</code></td><td style="text-align:left;"><strong>Accept Agency Invitation</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Chấp nhận lời mời tham gia <code>Agency</code> (và tự động gia nhập <code>Workspace</code> nếu lời mời có gán sẵn Workspace).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.10</code></strong></td><td style="text-align:center;"><code>UC-023</code></td><td style="text-align:left;"><strong>Decline Agency Invitation</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Từ chối lời mời tham gia <code>Agency</code>; cập nhật trạng thái lời mời thành <code>DECLINED</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.11</code></strong></td><td style="text-align:center;"><code>UC-024</code></td><td style="text-align:left;"><strong>Remove Agency Member</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Gỡ một thành viên ra khỏi <code>Agency</code> và thu hồi quyền truy cập của người đó tại các <code>Workspace</code> trực thuộc.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.12</code></strong></td><td style="text-align:center;"><code>UC-025</code></td><td style="text-align:left;"><strong>List Workspace</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem danh sách các <code>Workspace</code> được phép truy cập (hiển thị rõ badge chế độ <strong><code>Agency</code></strong> hoặc <strong><code>Cá nhân / Personal</code></strong>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.13</code></strong></td><td style="text-align:center;"><code>UC-026</code></td><td style="text-align:left;"><strong>Create Workspace</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Tạo mới một <code>Workspace</code> thuộc <code>Agency</code> với chế độ <code>workspaceMode = &quot;AGENCY&quot;</code> (dành cho khách hàng B2B) hoặc <code>workspaceMode = &quot;PERSONAL&quot;</code> (dành cho dự án cá nhân / nhóm nhỏ, tự động gán <code>Owner</code> làm <code>Manager</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.14</code></strong></td><td style="text-align:center;"><code>UC-027</code></td><td style="text-align:left;"><strong>View Workspace Dashboard</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem Bảng điều khiển tổng quan của <code>Workspace</code> (ở chế độ <code>PERSONAL</code>, hiển thị <strong>Bệ phóng Sáng tạo Cá nhân — Personal Quick Launchpad</strong> thay vì cảnh báo thiếu Gói dịch vụ).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.15</code></strong></td><td style="text-align:center;"><code>UC-028</code></td><td style="text-align:left;"><strong>Update Workspace</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Cập nhật thông tin cấu hình <code>Workspace</code> (Tên, Thương hiệu, Múi giờ, Mô tả) và <strong>chuyển đổi chế độ <code>workspaceMode</code> giữa <code>PERSONAL</code> và <code>AGENCY</code></strong>.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.16</code></strong></td><td style="text-align:center;"><code>UC-029</code></td><td style="text-align:left;"><strong>Delete Workspace</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Xóa mềm (<code>soft-delete</code>) một <code>Workspace</code> khỏi hệ thống.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.17</code></strong></td><td style="text-align:center;"><code>UC-030</code></td><td style="text-align:left;"><strong>Archive Workspace</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Lưu trữ (<code>ARCHIVE</code>) một <code>Workspace</code> đã kết thúc dự án để chuyển sang chế độ chỉ-đọc.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.18</code></strong></td><td style="text-align:center;"><code>UC-031</code></td><td style="text-align:left;"><strong>Restore Workspace</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Khôi phục (<code>RESTORE</code>) một <code>Workspace</code> từ trạng thái <code>ARCHIVED</code> về lại <code>ACTIVE</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.19</code></strong></td><td style="text-align:center;"><code>UC-032</code></td><td style="text-align:left;"><strong>Save Workspace Template</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Lưu cấu hình của một <code>Workspace</code> hiện tại thành mẫu (<code>Workspace Template</code>) để tái sử dụng cho các dự án tương tự.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.20</code></strong></td><td style="text-align:center;"><code>UC-033</code></td><td style="text-align:left;"><strong>View Workspace Templates</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Xem danh sách các mẫu <code>Workspace Template</code> đã lưu của <code>Agency</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.21</code></strong></td><td style="text-align:center;"><code>UC-034</code></td><td style="text-align:left;"><strong>Apply Workspace Template</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Áp dụng một mẫu <code>Workspace Template</code> khi khởi tạo hoặc thiết lập nhanh <code>Workspace</code> mới.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.22</code></strong></td><td style="text-align:center;"><code>UC-035</code></td><td style="text-align:left;"><strong>Delete Workspace Template</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Xóa một mẫu <code>Workspace Template</code> không còn sử dụng.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.23</code></strong></td><td style="text-align:center;"><code>UC-036</code></td><td style="text-align:left;"><strong>View Workspace Members</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem danh sách thành viên trong <code>Workspace</code> cùng vai trò cụ thể (<code>Manager</code>, <code>Creator</code>, <code>Client</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.24</code></strong></td><td style="text-align:center;"><code>UC-037</code></td><td style="text-align:left;"><strong>Add Workspace Member</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Thêm nhân sự từ <code>Agency</code> (với vai trò <code>Manager</code> / <code>Creator</code>) hoặc mời khách hàng (<code>Client</code> ở chế độ <code>AGENCY</code>) vào <code>Workspace</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.25</code></strong></td><td style="text-align:center;"><code>UC-038</code></td><td style="text-align:left;"><strong>Update Workspace Member Role</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Thay đổi vai trò của thành viên trong <code>Workspace</code> (ví dụ nâng <code>Creator</code> lên <code>Manager</code> hoặc chuyển quyền quản lý).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.26</code></strong></td><td style="text-align:center;"><code>UC-039</code></td><td style="text-align:left;"><strong>Remove Workspace Member</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Gỡ một thành viên ra khỏi <code>Workspace</code> (không được gỡ <code>Manager</code> duy nhất còn lại của Workspace).</td></tr></tbody></table><hr><h2 id="_2-đac-ta-nghiep-vu-quan-tri-agency-3-4-1-–-3-4-11" tabindex="-1">2. Đặc tả Nghiệp vụ Quản trị Agency (<code>3.4.1</code> – <code>3.4.11</code>) <a class="header-anchor" href="#_2-đac-ta-nghiep-vu-quan-tri-agency-3-4-1-–-3-4-11" aria-label="Permalink to &quot;2. Đặc tả Nghiệp vụ Quản trị Agency (`3.4.1` – `3.4.11`)&quot;">​</a></h2><h3 id="_2-1-vong-đoi-cong-ty-create-view-update-delete-agency-—-3-4-1-3-4-5" tabindex="-1">2.1. Vòng đời Công ty (<code>Create / View / Update / Delete Agency</code> — <code>3.4.1</code>..<code>3.4.5</code>) <a class="header-anchor" href="#_2-1-vong-đoi-cong-ty-create-view-update-delete-agency-—-3-4-1-3-4-5" aria-label="Permalink to &quot;2.1. Vòng đời Công ty (`Create / View / Update / Delete Agency` — `3.4.1`..`3.4.5`)&quot;">​</a></h3><ul><li><strong>Tạo Agency B2B (<code>3.4.1</code>)</strong>: <ul><li>Người dùng nhập Tên công ty (<code>name</code>, bắt buộc), Quy mô (<code>companySize</code>), Lĩnh vực (<code>category</code>), Tagline, Website, Địa chỉ.</li><li>Hệ thống tạo bản ghi <code>Agency</code> với <code>ownerId = currentUser.id</code>, thêm bản ghi <code>AgencyMember</code> (<code>status = ACTIVE</code>), khởi tạo gói cước mặc định (<code>Basic</code>) và ví AI Credit (<code>agency_credit_wallets</code>).</li></ul></li><li><strong>Tự động khởi tạo <code>Personal Hub Agency</code> (Luồng Bootstrap Cá nhân)</strong>: <ul><li>Khi người dùng cá nhân bấm <strong>&quot;Không gian Cá nhân (Personal Studio)&quot;</strong> (<code>POST /api/v1/workspaces/personal/bootstrap</code>), hệ thống tự động tạo ngầm một <code>Agency</code> cá nhân (<code>logoIcon = &quot;personal-studio&quot;</code>, <code>name = &quot;Personal Studio — &quot; + displayName</code>) nếu chưa có. Người dùng giữ vai trò <code>Owner</code> của <code>Personal Hub</code> này và được hưởng đầy đủ cơ chế Ví AI Credit + Gói cước mà không phải điền form thành lập công ty.</li></ul></li><li><strong>Xem Danh sách, Chi tiết &amp; Sơ đồ Tổ chức (<code>3.4.2</code>, <code>3.4.3</code>, <code>3.4.7</code>)</strong>: <ul><li>Trang <code>/agency/members</code> hỗ trợ 2 chế độ hiển thị: <strong>Dạng danh sách (<code>3.4.6</code>)</strong> và <strong>Sơ đồ tổ chức trực quan (<code>3.4.7</code>)</strong> thể hiện cấu trúc phân cấp từ <code>Owner</code> xuống từng <code>Workspace</code>, <code>Manager</code> và các <code>Creator</code>.</li></ul></li></ul><h3 id="_2-2-luong-loi-moi-thanh-vien-cong-ty-3-4-8-–-3-4-11" tabindex="-1">2.2. Luồng Lời mời Thành viên Công ty (<code>3.4.8</code> – <code>3.4.11</code>) <a class="header-anchor" href="#_2-2-luong-loi-moi-thanh-vien-cong-ty-3-4-8-–-3-4-11" aria-label="Permalink to &quot;2.2. Luồng Lời mời Thành viên Công ty (`3.4.8` – `3.4.11`)&quot;">​</a></h3><ul><li><strong>Gửi lời mời (<code>3.4.8 Invite Agency Member</code>)</strong>: <ul><li>Chỉ <code>Owner</code> thực hiện.</li><li>Hỗ trợ: <ol><li>Nhập email người nhận (kiểm tra không trùng thành viên đang <code>ACTIVE</code> hoặc lời mời <code>PENDING</code> còn hạn).</li><li>Chọn ngôn ngữ email mời (<code>Tiếng Việt</code> hoặc <code>English</code>) — có khung <strong>Xem trước trực tiếp (Live Email Preview)</strong> tự động co giãn chiều cao chuẩn xác, không bị cắt nội dung.</li><li>Nhập lời nhắn cá nhân hóa hoặc chọn từ mẫu email của công ty, đặt hạn hiệu lực lời mời (mặc định 7–30 ngày).</li><li>Tùy chọn gán trước <code>Workspace</code> và vai trò trong Workspace (<code>Manager</code> hoặc <code>Creator</code>).</li></ol></li></ul></li><li><strong>Chấp nhận / Từ chối lời mời (<code>3.4.9 Accept</code> &amp; <code>3.4.10 Decline</code>)</strong>: <ul><li>Người nhận mở link từ email hoặc xem thông báo lời mời trong ứng dụng: <ul><li>Nếu chọn <strong>Chấp nhận (<code>3.4.9</code>)</strong>: cập nhật lời mời sang <code>ACCEPTED</code>, kích hoạt <code>AgencyMember</code> (<code>status = ACTIVE</code>), và nếu lời mời có gán sẵn <code>Workspace</code> thì tự động thêm bản ghi <code>WorkspaceMember</code> tương ứng.</li><li>Nếu chọn <strong>Từ chối (<code>3.4.10</code>)</strong>: cập nhật lời mời sang <code>DECLINED</code>.</li></ul></li></ul></li><li><strong>Gỡ thành viên khỏi Agency (<code>3.4.11 Remove Agency Member</code>)</strong>: <ul><li><code>Owner</code> có thể gỡ thành viên khỏi Agency (không thể tự gỡ chính <code>Owner</code>). Khi bị gỡ khỏi Agency, thành viên cũng bị thu hồi quyền truy cập tại các Workspace thuộc Agency đó (trừ khi họ đang là <code>Manager</code> duy nhất của một Workspace đang chạy — hệ thống yêu cầu chuyển giao <code>Manager</code> trước).</li></ul></li></ul><hr><h2 id="_3-đac-ta-nghiep-vu-quan-tri-workspace-che-đo-personal-agency-3-4-12-–-3-4-26" tabindex="-1">3. Đặc tả Nghiệp vụ Quản trị Workspace &amp; Chế độ <code>PERSONAL | AGENCY</code> (<code>3.4.12</code> – <code>3.4.26</code>) <a class="header-anchor" href="#_3-đac-ta-nghiep-vu-quan-tri-workspace-che-đo-personal-agency-3-4-12-–-3-4-26" aria-label="Permalink to &quot;3. Đặc tả Nghiệp vụ Quản trị Workspace &amp; Chế độ `PERSONAL | AGENCY` (`3.4.12` – `3.4.26`)&quot;">​</a></h2><h3 id="_3-1-phan-loai-che-đo-workspacemode-agency-vs-personal" tabindex="-1">3.1. Phân loại Chế độ <code>workspaceMode</code> (<code>AGENCY</code> vs <code>PERSONAL</code>) <a class="header-anchor" href="#_3-1-phan-loai-che-đo-workspacemode-agency-vs-personal" aria-label="Permalink to &quot;3.1. Phân loại Chế độ `workspaceMode` (`AGENCY` vs `PERSONAL`)&quot;">​</a></h3><p>Mỗi bản ghi <code>Workspace</code> lưu thuộc tính <code>&quot;workspaceMode&quot;</code> bên trong cột JSONB <code>workspaces.settings</code>:</p><ul><li><strong><code>&quot;AGENCY&quot;</code> (Mặc định cho toàn bộ Workspace hiện có — AC2)</strong>: <ul><li>Phục vụ mô hình công ty truyền thông làm việc với khách hàng thương hiệu (<code>Client</code>).</li><li>Yêu cầu chỉ định <code>Manager</code> khi tạo, hiển thị đầy đủ 3 bước tiến trình (<code>1. Gói dịch vụ → 2. Chiến dịch → 3. Công việc</code>), Cổng Khách hàng (<code>Client Portal</code>) và phê duyệt 2 cấp.</li></ul></li><li><strong><code>&quot;PERSONAL&quot;</code> (Chế độ Không gian Cá nhân &amp; Nhóm nhỏ)</strong>: <ul><li>Phục vụ nhà sáng tạo độc lập (Solo Creator), Freelancer, Sinh viên làm đồ án/bài tập nhóm, Chủ shop nhỏ.</li><li>Khi tạo Workspace với <code>workspaceMode = &quot;PERSONAL&quot;</code>, nếu không truyền <code>managerId</code>, hệ thống <strong>tự động gán chính người tạo (<code>Owner</code>) làm <code>Manager</code></strong> của Workspace đó (AC3).</li><li>Bỏ qua bước <code>1. Gói dịch vụ</code>, không yêu cầu có <code>Client</code>, mở khóa tạo Chiến dịch tự do và Tạo Công việc độc lập đủ 8 loại <code>TaskType</code>, kèm nút <strong>Tự duyệt 1 chạm (<code>Self-Approve</code>)</strong>.</li></ul></li></ul><h3 id="_3-2-chuyen-đoi-che-đo-personal-↔-agency-3-4-15-update-workspace" tabindex="-1">3.2. Chuyển đổi Chế độ <code>PERSONAL ↔ AGENCY</code> (<code>3.4.15 Update Workspace</code>) <a class="header-anchor" href="#_3-2-chuyen-đoi-che-đo-personal-↔-agency-3-4-15-update-workspace" aria-label="Permalink to &quot;3.2. Chuyển đổi Chế độ `PERSONAL ↔ AGENCY` (`3.4.15 Update Workspace`)&quot;">​</a></h3><ul><li><strong>Nâng cấp từ <code>PERSONAL</code> → <code>AGENCY</code> (Scale-Up — AC4)</strong>: <ul><li>Khi dự án cá nhân hoặc nhóm nhỏ phát triển thành dự án có khách hàng (<code>Client</code>), <code>Owner</code> hoặc <code>Manager</code> vào trang Cài đặt Workspace (<code>/workspaces/:id/settings</code>) và bấm <strong>&quot;Nâng cấp sang chế độ Agency&quot;</strong>.</li><li>Hệ thống cập nhật <code>settings.workspaceMode = &quot;AGENCY&quot;</code>. Toàn bộ Chiến dịch, Công việc, Bài viết, Thư viện tư liệu, Lịch sử AI và Tài khoản MXH được <strong>giữ nguyên 100%</strong>. Giao diện lập tức mở khóa bước <code>1. Gói dịch vụ</code> và cho phép mời <code>Client</code> vào <code>Client Portal</code>.</li></ul></li><li><strong>Chuyển từ <code>AGENCY</code> → <code>PERSONAL</code> (Simplify — AC5)</strong>: <ul><li>Chỉ được phép thực hiện khi trong Workspace hiện <strong>không có thành viên nào giữ vai trò <code>Client</code> đang <code>ACTIVE</code></strong> và không có Công việc/Phần nào đang chờ <code>Client</code> duyệt. Nếu đang có <code>Client</code> hoạt động, Backend từ chối với mã lỗi <code>WORKSPACE_MODE_SWITCH_BLOCKED_BY_ACTIVE_CLIENT</code> (<code>409 Conflict</code>).</li></ul></li></ul><h3 id="_3-3-luu-tru-khoi-phuc-mau-khong-gian-3-4-17-–-3-4-22" tabindex="-1">3.3. Lưu trữ, Khôi phục &amp; Mẫu Không gian (<code>3.4.17</code> – <code>3.4.22</code>) <a class="header-anchor" href="#_3-3-luu-tru-khoi-phuc-mau-khong-gian-3-4-17-–-3-4-22" aria-label="Permalink to &quot;3.3. Lưu trữ, Khôi phục &amp; Mẫu Không gian (`3.4.17` – `3.4.22`)&quot;">​</a></h3><ul><li><strong>Lưu trữ &amp; Khôi phục (<code>3.4.17 Archive</code> &amp; <code>3.4.18 Restore</code>)</strong>: <ul><li><code>Owner</code> hoặc <code>Manager</code> có thể chuyển Workspace đã hoàn thành sang trạng thái <code>ARCHIVED</code> (mọi dữ liệu chuyển sang chỉ-đọc, dừng các job đăng bài tự động). Khi cần tiếp tục làm việc, gọi <code>Restore (3.4.18)</code> để đưa Workspace về <code>ACTIVE</code>.</li></ul></li><li><strong>Bộ Mẫu Không gian làm việc (<code>3.4.19 Save</code>, <code>3.4.20 View</code>, <code>3.4.21 Apply</code>, <code>3.4.22 Delete Workspace Template</code>)</strong>: <ul><li>Cho phép lưu cấu trúc thiết lập chuẩn của một Workspace (múi giờ, cấu hình quy trình, danh mục mẫu) thành <code>Workspace Template</code> để áp dụng nhanh cho các dự án mới cùng ngành hàng.</li></ul></li></ul><h3 id="_3-4-quan-ly-thanh-vien-trong-workspace-3-4-23-–-3-4-26" tabindex="-1">3.4. Quản lý Thành viên trong Workspace (<code>3.4.23</code> – <code>3.4.26</code>) <a class="header-anchor" href="#_3-4-quan-ly-thanh-vien-trong-workspace-3-4-23-–-3-4-26" aria-label="Permalink to &quot;3.4. Quản lý Thành viên trong Workspace (`3.4.23` – `3.4.26`)&quot;">​</a></h3><ul><li><strong>Xem danh sách thành viên (<code>3.4.23</code>)</strong>: Tất cả thành viên trong Workspace (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>) đều xem được danh sách thành viên của Workspace đó.</li><li><strong>Thêm thành viên (<code>3.4.24</code>)</strong>: <ul><li>Trong chế độ <code>AGENCY</code>: <code>Owner</code>/<code>Manager</code> thêm nhân sự từ Agency vào làm <code>Manager</code> hoặc <code>Creator</code>, và mời khách hàng vào làm <code>Client</code> (mỗi Workspace <code>AGENCY</code> gắn với 1 thương hiệu khách hàng).</li><li>Trong chế độ <code>PERSONAL</code>: Chủ không gian (<code>Owner</code>/<code>Manager</code>) có thể làm việc 1 mình (Solo) hoặc mời thêm các bạn cùng nhóm / cộng tác viên vào với vai trò <strong><code>Creator</code></strong> để cùng thực hiện các <code>Subtask</code> theo vai trò mà không cần có <code>Client</code>.</li></ul></li><li><strong>Cập nhật vai trò (<code>3.4.25</code>) &amp; Gỡ thành viên (<code>3.4.26</code>)</strong>: <ul><li>Đảm bảo quy tắc bất biến: <strong>Mỗi Workspace đang hoạt động phải luôn có ít nhất 1 <code>Manager</code> (<code>ACTIVE</code>)</strong>. Nếu muốn gỡ hoặc đổi vai trò của <code>Manager</code> duy nhất, phải chỉ định một <code>Manager</code> kế nhiệm trước.</li></ul></li></ul>',22)])])}const y=t(d,[["render",a]]);export{u as __pageData,y as default};
